import{_ as h,o as t,c as a,a2 as c}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Một node, nhiều cách dạy","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/cach-day.md","filePath":"decisions/cach-day.md"}'),i={name:"decisions/cach-day.md"};function o(e,n,g,r,u,l){return t(),a("div",null,[...n[0]||(n[0]=[c('<h1 id="mot-node-nhieu-cach-day" tabindex="-1">Một node, nhiều cách dạy <a class="header-anchor" href="#mot-node-nhieu-cach-day" aria-label="Permalink to &quot;Một node, nhiều cách dạy&quot;">​</a></h1><p>Trên trang này# Một node, nhiều cách dạy <a href="#mot-node-nhieu-cach-day">​</a> Hệ thống không chỉ quyết định learner nên học <strong>phần kiến thức nào</strong> tiếp theo. Nó còn quyết định phần đó nên được dạy <strong>theo cách nào</strong> — và với hai learner khác nhau, câu trả lời thường khác nhau.</p><h2 id="kien-thuc-va-cach-day-la-hai-thu-tach-roi-​" tabindex="-1">Kiến thức và cách dạy là hai thứ tách rời <a href="#kien-thuc-va-cach-day-la-hai-thu-tach-roi">​</a> <a class="header-anchor" href="#kien-thuc-va-cach-day-la-hai-thu-tach-roi-​" aria-label="Permalink to &quot;Kiến thức và cách dạy là hai thứ tách rời [​](#kien-thuc-va-cach-day-la-hai-thu-tach-roi)&quot;">​</a></h2><p>Đây là một trong những quyết định kiến trúc quan trọng nhất của Nemo12: Knowledge Node <strong>không</strong> chứa cách dạy. Một node chỉ lưu những gì đúng bất kể ai đang học: textKN-ALG-FACTOR-001 · Đặt nhân tử chung Kiến thức nền cần có: phép nhân · tính chất phân phối · ước số · biểu thức đại số Nội dung: ab + ac = a(b + c)Không có một chữ nào về việc nên giải thích trước hay cho bài toán trước, nên mất 15 phút hay 40 phút, nên có gợi ý hay không. Vì những thứ đó <strong>không thuộc về kiến thức</strong> — chúng thuộc về learner đang đứng trước kiến thức đó.</p><h2 id="bon-goi-hoc-cho-cung-mot-node-​" tabindex="-1">Bốn gói học cho cùng một node <a href="#bon-goi-hoc-cho-cung-mot-node">​</a> <a class="header-anchor" href="#bon-goi-hoc-cho-cung-mot-node-​" aria-label="Permalink to &quot;Bốn gói học cho cùng một node [​](#bon-goi-hoc-cho-cung-mot-node)&quot;">​</a></h2><p>Phía trên mỗi Knowledge Node có thể tồn tại nhiều Learning Experience khác nhau. Cùng node &quot;đặt nhân tử chung&quot; ở trên:</p><h3 id="goi-a-—-thanh-thuc-​" tabindex="-1">Gói A — Thành thục <a href="#goi-a-—-thanh-thuc">​</a> <a class="header-anchor" href="#goi-a-—-thanh-thuc-​" aria-label="Permalink to &quot;Gói A — Thành thục [​](#goi-a-—-thanh-thuc)&quot;">​</a></h3><p><strong>Cho learner:</strong> còn ba ngày nữa thi. textKhoảng 15 phút. Mục tiêu là làm đúng và làm nhanh. Đây chính là điểm mạnh của lối luyện dạng truyền thống, và trong hoàn cảnh này nó là lựa chọn đúng.</p><h3 id="goi-b-—-kham-pha-​" tabindex="-1">Gói B — Khám phá <a href="#goi-b-—-kham-pha">​</a> <a class="header-anchor" href="#goi-b-—-kham-pha-​" aria-label="Permalink to &quot;Gói B — Khám phá [​](#goi-b-—-kham-pha)&quot;">​</a></h3><p><strong>Cho learner:</strong> có thời gian, và cần hiểu bản chất. textBài toán thách thức → tự thử → gợi ý → phát hiện → giải thích → tổng quát hoá → bài chuyển dạngKhoảng 40 phút. Đây là <a href="/ideas/aops">tinh thần AoPS</a>: công thức xuất hiện ở cuối, như thứ learner vừa tìm ra.</p><h3 id="goi-c-—-va-nen-​" tabindex="-1">Gói C — Vá nền <a href="#goi-c-—-va-nen">​</a> <a class="header-anchor" href="#goi-c-—-va-nen-​" aria-label="Permalink to &quot;Gói C — Vá nền [​](#goi-c-—-va-nen)&quot;">​</a></h3><p><strong>Cho learner:</strong> chưa nắm tính chất phân phối. Hệ thống <strong>không dạy tiếp</strong> phần phân tích nhân tử. Nó lùi xuống mắt xích nền, xây lại từ rồi mới quay lên. Đây là <a href="/ideas/mastery-learning">mastery learning</a> đúng nghĩa: không xây tiếp trên nền đang nứt.</p><h3 id="goi-d-—-thi-đau-​" tabindex="-1">Gói D — Thi đấu <a href="#goi-d-—-thi-đau">​</a> <a class="header-anchor" href="#goi-d-—-thi-đau-​" aria-label="Permalink to &quot;Gói D — Thi đấu [​](#goi-d-—-thi-đau)&quot;">​</a></h3><p><strong>Cho learner:</strong> đã vững node cơ bản. Đưa thẳng và <strong>không</strong> kèm câu &quot;hãy phân tích bằng phương pháp đặt nhân tử chung&quot; — vì <a href="/ideas/aops">câu đó đã tiết lộ chiến lược</a>. Learner phải tự nhận ra rằng cần nhóm lại: text</p><h2 id="he-thong-chon-goi-nao-dua-tren-cai-gi-​" tabindex="-1">Hệ thống chọn gói nào, dựa trên cái gì <a href="#he-thong-chon-goi-nao-dua-tren-cai-gi">​</a> <a class="header-anchor" href="#he-thong-chon-goi-nao-dua-tren-cai-gi-​" aria-label="Permalink to &quot;Hệ thống chọn gói nào, dựa trên cái gì [​](#he-thong-chon-goi-nao-dua-tren-cai-gi)&quot;">​</a></h2><p>Đây là chỗ <a href="/learner/learner-model">Learner Model</a> trở nên thật sự có giá trị. Hai chiều đo khác nhau, và chúng có thể lệch nhau rất xa: Learner đang ở đâuGói phù hợpHiểu bản chất tốt, nhưng làm chậm và hay sai vặt<strong>A</strong> — luyện cho thành thụcLàm nhanh và chính xác, nhưng gặp bài lạ thì đứng hình<strong>B</strong> — bài không theo dạng, tự chọn phương phápCả hai đều tốt<strong>D</strong> — bài thi đấuChưa nắm khái niệm<strong>C</strong> — quay xuống nền, dùng hình ảnh và vật cụ thểDòng thứ hai là dòng đáng chú ý nhất. Một learner làm đúng 200 bài cùng dạng trông rất giỏi trên bảng điểm — nhưng nếu em ấy chưa bao giờ phải tự chọn công cụ, thì <strong>thêm 200 bài nữa cũng không sửa được</strong> khoảng trống đó. Cần đổi loại trải nghiệm, không phải tăng số lượng. Và ngược lại: một learner hiểu rất sâu nhưng chưa thành thục thì không cần thêm bài khám phá — em ấy cần luyện cho quen tay. Cho gói B lúc này là lãng phí thời gian của một đứa trẻ.</p><h2 id="vi-sao-phai-tach-nhu-vay-​" tabindex="-1">Vì sao phải tách như vậy <a href="#vi-sao-phai-tach-nhu-vay">​</a> <a class="header-anchor" href="#vi-sao-phai-tach-nhu-vay-​" aria-label="Permalink to &quot;Vì sao phải tách như vậy [​](#vi-sao-phai-tach-nhu-vay)&quot;">​</a></h2><p>Nếu cách dạy bị gắn cứng vào kiến thức, mỗi node chỉ có đúng một con đường đi qua nó. Khi đó hệ thống chỉ còn hai lựa chọn: cho learner đi qua, hoặc không cho. Tách ra thì mỗi node có nhiều con đường, và câu hỏi đổi từ <em>&quot;learner đã đủ trình độ học phần này chưa?&quot;</em> thành một câu hữu ích hơn nhiều: <em>&quot;Với learner này, lúc này, phần này nên được dạy theo cách nào?&quot;</em> Nó cũng có một hệ quả thực tế: khi Nemo12 tìm ra một cách dạy tốt hơn cho một node, <strong>kiến thức không cần sửa gì cả</strong>. Chỉ có gói học được thêm vào. Ngược lại, khi chương trình thay đổi, các gói học vẫn dùng lại được.</p><h2 id="nguyen-tac-​" tabindex="-1">Nguyên tắc <a href="#nguyen-tac">​</a> <a class="header-anchor" href="#nguyen-tac-​" aria-label="Permalink to &quot;Nguyên tắc [​](#nguyen-tac)&quot;">​</a></h2><p>textCoral quản lý → CÁI GÌ cần được học Learning Engine quyết định → learner NÀY nên học nó THẾ NÀO, LÚC NÀYKiến thức thì tương đối ổn định. Cách dạy thì phải thích ứng. Đây cũng là lý do Pearl không xếp hạng các trường phái giáo dục. <a href="/ideas/">Mỗi trường phái giải một bài toán khác nhau</a> — và trong một hệ thống cá nhân hoá, chúng không phải các phe để chọn, mà là <strong>các gói học để chọn đúng lúc</strong>. <a href="/decisions/">Quay lại: Nemo12 ra quyết định thế nào →</a></p>',20)])])}const p=h(i,[["render",o]]);export{s as __pageData,p as default};
